import React, { useState, useEffect } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg'; 

const QuanLyCuDan = () => {
    const [selectedRoom, setSelectedRoom] = useState(null);
    const [info, setInfo] = useState(null); // Mặc định là null (chưa có dữ liệu)
    const [loading, setLoading] = useState(false);

    const allRooms = [];
    for (let floor = 1; floor <= 9; floor++) {
        for (let num = 1; num <= 5; num++) {
            allRooms.push(`${floor}0${num}`);
        }
    }

    useEffect(() => {
        if (!selectedRoom) return;

        const fetchResidentData = async () => {
            setLoading(true);
            try {
                // SAU NÀY: Gọi API lấy dữ liệu từ Backend đã được cư dân khai báo
                // const res = await fetch(`/api/residents/${selectedRoom}`);
                // const data = await res.json();

                // HIỆN TẠI: Giả lập trả về null vì chưa ai khai báo tài khoản
                setTimeout(() => {
                    const dataFromDatabase = null; // Giả lập database trống
                    setInfo(dataFromDatabase);
                    setLoading(false);
                }, 300);

            } catch (error) {
                console.error("Lỗi Backend:", error);
                setLoading(false);
            }
        };

        fetchResidentData();
    }, [selectedRoom]);

    return (
        <div style={{
            flex: 1, borderRadius: '30px', display: 'flex', flexDirection: 'column', 
            backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover',
            backgroundPosition: 'center', overflow: 'hidden', height: 'calc(100vh - 120px)'
        }} className="glass-card">

            <div style={{ padding: '20px', color: '#fff' }}>
                <h2 style={{ margin: 0, textShadow: '1px 1px 4px rgba(0,0,0,0.5)' }}>Quản lý cư dân</h2>
            </div>

            <div style={{ flex: 1, padding: '0 20px 20px 20px', display: 'flex', gap: '25px', overflow: 'hidden' }}>

                {/* DANH SÁCH PHÒNG */}
                <div className="custom-scrollbar" style={{ 
                    width: '210px', display: 'grid', gridTemplateColumns: 'repeat(5, 1fr)', 
                    gap: '6px', alignContent: 'flex-start', overflowY: 'auto',
                    padding: '12px', backgroundColor: 'rgba(0,0,0,0.3)', borderRadius: '20px'
                }}>
                    {allRooms.map(room => (
                        <div 
                            key={room} 
                            onClick={() => setSelectedRoom(room)}
                            style={{ 
                                background: selectedRoom === room ? '#8b5e5e' : 'rgba(255,255,255,0.85)', 
                                color: selectedRoom === room ? 'white' : '#333',
                                padding: '8px 0', borderRadius: '8px', textAlign: 'center', 
                                fontSize: '11px', fontWeight: 'bold', cursor: 'pointer'
                            }}
                        >
                            {room}
                        </div>
                    ))}
                </div>

                {/* CHI TIẾT CƯ DÂN */}
                <div style={{ 
                    flex: 1, backgroundColor: '#ffffff', borderRadius: '30px', 
                    padding: '40px', display: 'flex', flexDirection: 'column',
                    color: '#000', boxShadow: '0 10px 30px rgba(0,0,0,0.2)'
                }}>
                    {loading ? (
                        <div style={{ flex: 1, display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
                            Đang kiểm tra dữ liệu hệ thống...
                        </div>
                    ) : selectedRoom ? (
                        info ? (
                            // Giao diện khi ĐÃ CÓ dữ liệu từ Backend
                            <div style={{ animation: 'fadeIn 0.4s' }}>
                                <h1 style={{ fontSize: '60px', margin: '0 0 30px 0', color: '#222', fontWeight: '800' }}>
                                    PHÒNG {selectedRoom}
                                </h1>
                                <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
                                    <InfoBlock label="Chủ hộ" value={info.name} bold />
                                    <InfoBlock label="SĐT" value={info.phone} />
                                    <InfoBlock label="Thành viên" value={info.members} />
                                </div>
                            </div>
                        ) : (
                            // Giao diện khi CHƯA CÓ tài khoản nào khai báo (info === null)
                            <div style={{ flex: 1, display: 'flex', flexDirection: 'column', justifyContent: 'center', alignItems: 'center', textAlign: 'center' }}>
                                <div style={{ fontSize: '60px', marginBottom: '20px' }}>⚠️</div>
                                <h2 style={{ color: '#8b5e5e' }}>Phòng {selectedRoom} chưa khai báo</h2>
                                <p style={{ color: '#777', maxWidth: '300px' }}>
                                    Cư dân phòng này chưa tạo tài khoản hoặc chưa cập nhật thông tin lên hệ thống.
                                </p>
                            </div>
                        )
                    ) : (
                        <div style={{ flex: 1, display: 'flex', justifyContent: 'center', alignItems: 'center', color: '#aaa', fontStyle: 'italic' }}>
                            Chọn một phòng để xem trạng thái cư dân...
                        </div>
                    )}
                </div>
            </div>
            <style>{`
                .custom-scrollbar::-webkit-scrollbar { width: 5px; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.2); border-radius: 10px; }
            `}</style>
        </div>
    );
};

const InfoBlock = ({ label, value, bold }) => (
    <div style={{ display: 'flex', borderBottom: '1px solid #eee', paddingBottom: '10px' }}>
        <span style={{ width: '200px', color: '#888' }}>{label}</span>
        <span style={{ fontWeight: bold ? '700' : '500', fontSize: '20px' }}>{value}</span>
    </div>
);

export default QuanLyCuDan;
